 out=Path(out);roles={'ego','initial_crossing','further_crossing'};reference=json.loads((out/'measured-reference-event.json').read_text()) if (out/'measured-reference-event.json').exists() else None;matched=min(rows,key=lambda r:abs(r['time_s']-reference['time_s'])) if rows and reference else None
