 complete=all(checks.values());result={'status':'draft','cell_id':cfg['cell_id'],'actor':cfg['actor'],'case_id':cfg['case_id'],'input_revision':cfg['input_revision'],'primary_video_reference':'overview.mkv','setup_confirmed':bool(rows),'behavior_attempted':any(r['states']['ego']['speed_mps']>0 for r in rows),'maneuver_completed':complete,'termination_reason':'complete_original_history' if complete else 'incomplete_physical_or_observation_contract','physical_failure_flags':{'collision':bool(report['contacts']),'roadway_departure':not checks['all_bodies_on_operating_pavement']},'target_checks':target_checks,'measured_values':{'frames':len(rows),'duration_s':rows[-1]['time_s'] if rows else 0,'whole_body_clearance_times_s':clearance,'reference_time_s':None if matched is None else matched['time_s'],'actual_stopping_measurement':stopping},'trace_reference':'trace.jsonl','video_references':['overview.mkv','approach.mkv','reference_corner.mkv','driver_reference.mkv'],'video_frame_map_reference':'video_frames.jsonl','recording_description':cfg['recording_description'],'recording_evidence':[{'name':c['name'],'unit':c['unit'],'reference':'channels/'+c['name']+'.jsonl'} for c in cfg['recording_description']['channels']]+[{'name':c['name'],'unit':c['unit'],'reference':'context.json'} for c in cfg['recording_description']['context_inputs']],'realized_observables':realized,'recording_complete':len(rows)==cfg['maximum_frames'] and error is None,'requested_variable_assignments':{k:v for k,v in cfg['variable_assignments'].items() if v['kind'] in ['world_setup','controller']},'authored_context':cfg['authored_test_context'],'error':error,'restoration':{'restored':report['restored']},'limitations':cfg['recording_description']['limitations'],'judgments_unresolved':['proceed cautiously','immediate hazard','yielding to vehicles not so obligated'],'video_Core_pair_accepted':False}
